const int N = 300300;

int n, a[N];

bool read() {
	if (!(cin >> n)) return false;
	forn(i, n) assert(scanf("%d", &a[i]) == 1);
	return true;
}

void solve() {
	sort(a, a + n);

	li suml = 0, sumr = accumulate(a, a + n, 0ll);
	li ansv = LLONG_MAX, ansp = LLONG_MIN;
	forn(i, n) {
		li curv = li(i) * a[i] - suml;
		curv += sumr - li(n - i) * a[i];
		if (ansv > curv) {
			ansv = curv;
			ansp = a[i];
		}
		suml += a[i];
		sumr -= a[i];
	}
	assert(sumr == 0);

	assert(ansv != LLONG_MAX);
	cerr << "ansv: " << ansv << endl;
	cout << ansp << endl;
}

