struct blocks {
	int root[LOGN];
	vector<int> block[LOGN];

	void clear() {
		forn(i, LOGN) {
			block[i].clear();
			root[i] = get_idx();
		}
	}

	void insert(int i) {
		vector<int> cur(1, i);
		forn(i, LOGN)
			if (sz(block[i]) == sz(cur)) {
				cur.insert(cur.end(), all(block[i]));
				block[i].clear();
				root[i] = build(root[i], block[i]);
			} else {
				block[i] = cur;
				root[i] = build(root[i], block[i]);
				break;
			}
	}

	li calc2(int idx) {
		li ans = 0;
		forn(i, LOGN) {
			ans += calc(root[i], idx);
		}
		return ans;
	}
};

char buf[N];
blocks z1, z2;

void solve() {
	ids.clear();
	nfor(i, N) ids.pb(i);

	z1.clear();
	z2.clear();

	forn(i, m) {
		int type;
		assert(scanf("%d%s", &type, buf) == 2);
		a[i] = buf;

		if (type == 1) {
			z1.insert(i);
		} else if (type == 2) {
			z2.insert(i);
		} else if (type == 3) {
			li ans = z1.calc2(i) - z2.calc2(i);
			printf("%lld\n", ans);
			fflush(stdout);
		} else throw;
	}
}
